import * as THREE from ${JSON.stringify(h)}

/** @typedef {{group:THREE.Group, front:THREE.Mesh, u:number, imgIdx:number}} Item */

let renderer /** @type {THREE.WebGLRenderer|undefined} */
let scene /** @type {THREE.Scene|undefined} */
let camera /** @type {THREE.PerspectiveCamera|undefined} */
let belt /** @type {THREE.Group|undefined} */

let items = /** @type {Item[]} */([])
let textures = /** @type {(THREE.Texture|null)[]} */([])
let frontGeom /** @type {THREE.BufferGeometry|undefined} */

const prm = {
  count: 12,
  scrollSpeed: 0,
  spinDeg: 0,
  phaseStepDeg: 10,
  spacing: 56,
  cardW: 180,
  cardH: 220,
  radius: 18,
  curveAmp: 120,
  angleDeg: -12,
  tiltYdeg: 8,
  camYawDeg: 12,
  camPitchDeg: -6,
  camRollDeg: 0,
  camDist: 900,
  camFovDeg: 32,
  camTargetX: 0,
  camTargetY: 0,
  camTargetZ: 0,
}

let last = performance.now()
let tSec = 0
let animating = false
const deg2rad = (d) => d * Math.PI / 180
const clampDpr = (d) => Math.min(Math.max(d || 1, 1), 1.5)
const smooth01 = (t) => t <= 0 ? 0 : t >= 1 ? 1 : t * t * (3 - 2 * t)

const postProgress = (loaded, total) => {
  try { self.postMessage({ type: 'progress', loaded, total }) } catch {}
}
const postReady = () => {
  try { self.postMessage({ type: 'ready' }) } catch {}
}

const clampR = (w, h, r) => Math.max(0, Math.min(r, Math.min(w, h) / 2))
const makeShape = (w, h, r) => {
  const c = clampR(w, h, r)
  const s = new THREE.Shape()
  const hw = w / 2, hh = h / 2
  s.moveTo(-hw + c, -hh)
  s.lineTo(hw - c, -hh)
  s.absarc(hw - c, -hh + c, c, -Math.PI / 2, 0)
  s.lineTo(hw, hh - c)
  s.absarc(hw - c, hh - c, c, 0, Math.PI / 2)
  s.lineTo(-hw + c, hh)
  s.absarc(-hw + c, hh - c, c, Math.PI / 2, Math.PI)
  s.lineTo(-hw, -hh + c)
  s.absarc(-hw + c, -hh + c, c, Math.PI, 1.5 * Math.PI)
  return s
}

const makeFrontGeom = (w, h, r) => {
  const g = new THREE.ShapeGeometry(makeShape(w, h, r), 8)
  g.computeBoundingBox()
  const bb = g.boundingBox
  const minX = bb.min.x, minY = bb.min.y
  const invW = 1 / (bb.max.x - bb.min.x)
  const invH = 1 / (bb.max.y - bb.min.y)
  const pos = g.attributes.position
  const uv = new THREE.BufferAttribute(new Float32Array(pos.count * 2), 2)
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), y = pos.getY(i)
    uv.setXY(i, (x - minX) * invW, (y - minY) * invH)
  }
  g.setAttribute("uv", uv)
  g.computeBoundingSphere?.()
  return g
}

const applyCover = (tex) => {
  if (!tex || !tex.image) return
  const iw = tex.image.width || 1
  const ih = tex.image.height || 1
  const aImg = iw / ih
  const aCard = prm.cardW / prm.cardH
  if (aImg > aCard) {
    const rx = aCard / aImg
    tex.repeat.set(rx, 1)
    tex.offset.set((1 - rx) / 2, 0)
  } else {
    const ry = aImg / aCard
    tex.repeat.set(1, ry)
    tex.offset.set(0, (1 - ry) / 2)
  }
  tex.needsUpdate = true
}

const makeFrontMat = (map) => {
  const m = new THREE.MeshBasicMaterial({
    color: 0xffffff,
    toneMapped: false,
    side: THREE.DoubleSide,
    transparent: true,
    depthWrite: false,
    depthTest: true,
    map: map ?? null,
  })
  if (m.map) applyCover(m.map)
  return m
}

const setCamera = () => {
  const a = prm
  camera.fov = a.camFovDeg
  camera.updateProjectionMatrix()
  const yaw = deg2rad(a.camYawDeg)
  const pitch = deg2rad(a.camPitchDeg)
  const r = a.camDist
  const tx = a.camTargetX, ty = a.camTargetY, tz = a.camTargetZ
  camera.position.set(
    tx + r * Math.sin(yaw) * Math.cos(pitch),
    ty + r * Math.sin(pitch),
    tz + r * Math.cos(yaw) * Math.cos(pitch)
  )
  camera.lookAt(tx, ty, tz)
  camera.rotation.z = deg2rad(a.camRollDeg)
}

const buildItems = (N) => {
  for (const it of items) {
    if (it.front?.material) it.front.material.dispose?.()
    belt.remove(it.group)
  }
  items = []
  const M = Math.max(1, textures.length)
  const half = ((N - 1) * prm.spacing) / 2
  for (let i = 0; i < N; i++) {
    const grp = new THREE.Group()
    const mat = makeFrontMat(textures[i % M] || null)
    const front = new THREE.Mesh(frontGeom, mat)
    front.renderOrder = 2
    grp.add(front)
    belt.add(grp)
    items.push({ group: grp, front, u: -half + i * prm.spacing, imgIdx: i % M })
  }
}

const updateItemMaps = () => {
  const M = Math.max(1, textures.length)
  for (const it of items) {
    const m = it.front.material
    m.map = textures[it.imgIdx % M] || null
    if (m.map) applyCover(m.map)
    m.needsUpdate = true
  }
}

const loadTextures = async (urls) => {
  // Emit progress for 0 images case
  if (!urls || urls.length === 0) {
    textures.forEach((t) => t?.dispose?.())
    textures = []
    postProgress(1, 1)
    return
  }
  // Use ImageBitmapLoader in worker environment
  textures.forEach((t) => t?.dispose?.())
  textures = []
  const ibl = new THREE.ImageBitmapLoader()
  ibl.setOptions({ imageOrientation: 'flipY', premultiplyAlpha: 'none' })
  const maxAniso = (renderer?.capabilities?.getMaxAnisotropy?.() ?? 8)
  let loaded = 0
  const total = urls.length
  const promises = urls.map((u, i) => new Promise((resolve) => {
    if (!u) {
      textures[i] = null
      loaded++
      postProgress(loaded, total)
      resolve()
      return
    }
    ibl.load(u, (bitmap) => {
      const t = new THREE.Texture(bitmap)
      t.needsUpdate = true
      t.flipY = false
      t.colorSpace = THREE.SRGBColorSpace
      t.anisotropy = Math.min(4, maxAniso)
      applyCover(t)
      textures[i] = t
      loaded++
      postProgress(loaded, total)
      resolve()
    }, undefined, () => {
      textures[i] = null
      loaded++
      postProgress(loaded, total)
      resolve()
    })
  }))
  await Promise.all(promises)
}

const resizeCamera = () => {
  const v = new THREE.Vector2()
  renderer.getSize(v)
  camera.aspect = Math.max(1e-6, v.x / Math.max(1e-6, v.y))
  camera.updateProjectionMatrix()
}

const updateAnimLoop = () => {
  const need = Math.abs(prm.scrollSpeed) > 0 || Math.abs(prm.spinDeg) > 0
  if (need && !animating) {
    animating = true
    last = performance.now()
    renderer.setAnimationLoop(loop)
  } else if (!need && animating) {
    animating = false
    renderer.setAnimationLoop(null)
    // Render one final frame to reflect latest props
    loop(true)
  }
}

const loop = (single = false) => {
  const now = performance.now()
  const dt = Math.min(0.05, (now - last) / 1000)
  last = now
  tSec += dt

  setCamera()

  const N = items.length
  const spacingNow = prm.spacing
  const period = N * spacingNow
  const half = ((N - 1) * spacingNow) / 2

  const dx = -prm.scrollSpeed * spacingNow * dt
  let sumY = 0

  for (let k = 0; k < N; k++) {
    const it = items[k]
    it.u += dx

    const fadeW = (N <= 3) ? 0 : Math.max(0, spacingNow * 1.1)
    const edgeL = -half, edgeR = half
    const rampL = fadeW > 0 ? Math.min(1, Math.max(0, (it.u - edgeL) / fadeW)) : 1
    const rampR = fadeW > 0 ? Math.min(1, Math.max(0, (edgeR - it.u) / fadeW)) : 1
    const op = smooth01(Math.min(rampL, rampR))

    if (fadeW > 0) {
      if (it.u < edgeL - 0.5 * fadeW) {
        it.u += period
      } else if (it.u > edgeR + 0.5 * fadeW) {
        it.u -= period
      }
    }

    const y = prm.curveAmp * Math.sin(0.055 * it.u)
    const z = 0.06 * prm.curveAmp * Math.cos(0.055 * it.u)
    sumY += y
    it.group.position.set(it.u, y, z)

    const tiltY = deg2rad(prm.tiltYdeg)
    const spinVel = deg2rad(prm.spinDeg)
    const phaseStep = deg2rad(prm.phaseStepDeg)
    const s = it.u / spacingNow
    const spin = spinVel * tSec + phaseStep * s
    it.group.rotation.set(0, tiltY, spin)

    const m = it.front.material
    m.opacity = op
    it.group.visible = op > 0.001
  }

  const avgY = N > 0 ? sumY / N : 0
  const padY = 40
  belt.position.y = -avgY + padY
  belt.rotation.z = deg2rad(prm.angleDeg)

  renderer.render(scene, camera)

  if (single) return
}

self.onmessage = async (ev) => {
  const data = ev.data
  if (!data || !data.type) return

  if (data.type === 'init') {
    const { canvas, size, dpr, props, images } = data
    renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true, powerPreference: 'high-performance' })
    renderer.setClearAlpha(0)
    renderer.setPixelRatio(clampDpr(dpr))
    renderer.setSize(size.w, size.h, false)
    renderer.outputColorSpace = THREE.SRGBColorSpace

    scene = new THREE.Scene()
    camera = new THREE.PerspectiveCamera(props.camFovDeg, Math.max(1e-6, size.w) / Math.max(1e-6, size.h), 0.1, 5000)
    scene.add(new THREE.AmbientLight(0xffffff, 0.9))

    belt = new THREE.Group()
    scene.add(belt)

    Object.assign(prm, props)
    frontGeom = makeFrontGeom(prm.cardW, prm.cardH, prm.radius)

    await loadTextures(images)
    buildItems(Math.max(2, prm.count))
    resizeCamera()
    updateItemMaps()

    // Decide on animation
    const need = Math.abs(prm.scrollSpeed) > 0 || Math.abs(prm.spinDeg) > 0
    if (need) {
      animating = true
      last = performance.now()
      renderer.setAnimationLoop(loop)
    } else {
      loop(true)
    }

    // Signal ready after first draw
    postReady()
  }

  if (data.type === 'resize') {
    const { size, dpr } = data
    renderer.setPixelRatio(clampDpr(dpr))
    renderer.setSize(size.w, size.h, false)
    resizeCamera()
    if (!animating) loop(true)
  }

  if (data.type === 'props') {
    const props = data.props
    const wChanged = props.cardW !== undefined && props.cardW !== prm.cardW
    const hChanged = props.cardH !== undefined && props.cardH !== prm.cardH
    const rChanged = props.radius !== undefined && props.radius !== prm.radius

    Object.assign(prm, props)

    if (wChanged || hChanged || rChanged) {
      frontGeom?.dispose?.()
      frontGeom = makeFrontGeom(prm.cardW, prm.cardH, prm.radius)
      for (const it of items) it.front.geometry = frontGeom
    }

    if (props.count !== undefined) buildItems(Math.max(2, prm.count))

    updateItemMaps()
    updateAnimLoop()
    if (!animating) loop(true)
  }

  if (data.type === 'images') {
    await loadTextures(data.images)
    updateItemMaps()
    if (!animating) loop(true)
    // Signal ready after images swapped
    postReady()
  }
}

function wrapLon(lon){ return ((lon + 540) % 360) - 180; }
function sampleEdgeFlat(ring, maxDegStep){
    var out = [];
    for (var i=0;i<ring.length-2;i+=2){
        var lon1 = ring[i],   lat1 = ring[i+1];
        var lon2 = ring[i+2], lat2 = ring[i+3];
        var dLon = lon2 - lon1, lon2n = lon2;
        if (Math.abs(dLon)>180){ lon2n += dLon>0?-360:360; dLon = lon2n - lon1; }
        var dLat = lat2 - lat1;
        var maxSpan = Math.max(Math.abs(dLon), Math.abs(dLat));
        var steps = Math.max(1, Math.ceil(maxSpan / maxDegStep));
        for (var s=0;s<=steps;s++){
            var t = s/steps;
            var lon = lon1 + dLon*t;
            var lat = lat1 + dLat*t;
            out.push(wrapLon(lon), lat);
        }
    }
    return new Float32Array(out);
}
function lonLatToVec3(lon,lat,r){
    if (r === void 0) r = 1;
    var phi = (90 - lat) * Math.PI/180;
    var theta = (lon + 180) * Math.PI/180;
    return [-Math.sin(phi) * Math.cos(theta), Math.cos(phi), Math.sin(phi) * Math.sin(theta)];
}
onmessage = function(e){
    var densityDeg = e.data.densityDeg, polysIn = e.data.polysIn;
    var edgeOut = [];
    for (var p=0;p<polysIn.length;p++){
        var poly = polysIn[p];
        for (var r=0;r<poly.length;r++){
            var sampled = sampleEdgeFlat(poly[r], Math.max(0.2, densityDeg));
            for (var i=0;i<sampled.length;i+=2){
                var v = lonLatToVec3(sampled[i], sampled[i+1], 1);
                edgeOut.push(v[0],v[1],v[2]);
            }
        }
    }
    var arr = new Float32Array(edgeOut);
    postMessage({ ok:true, edge:arr }, [arr.buffer]);
};

var PI=Math.PI;
function wrap180(lon){ return ((lon+540)%360)-180; }
function vec3(lon,lat){
  var phi=(90-lat)*PI/180, th=(lon+180)*PI/180;
  return [-Math.sin(phi)*Math.cos(th), Math.cos(phi), Math.sin(phi)*Math.sin(th)];
}
function unwrapRing(ring, refLon){
  var out=new Array(ring.length), prev=null;
  for(var i=0;i<ring.length;i++){
    var L=ring[i][0], A=ring[i][1];
    var d=L-refLon;
    if(d>180) L-=360; else if(d<-180) L+=360;
    if(prev){
      var step=L-prev[0];
      if(step>180) L-=360; else if(step<-180) L+=360;
    }
    out[i]=[L,A]; prev=out[i];
  }
  return out;
}
function pointInRing(pt, ring){
  var x=pt[0], y=pt[1], inside=false, n=ring.length;
  for(var i=0,j=n-1;i<n;j=i++){
    var xi=ring[i][0], yi=ring[i][1];
    var xj=ring[j][0], yj=ring[j][1];
    var denom=yj-yi; if(denom===0) continue;
    var inter=((yi>y)!==(yj>y)) && (x < (xj-xi)*(y-yi)/denom + xi);
    if(inter) inside=!inside;
  }
  return inside;
}
function containsUnwrapped(poly, refLon, lon, lat){
  var rings=poly.coordinates; if(!rings||!rings.length) return false;
  var r0=unwrapRing(rings[0], refLon);
  var pt=[lon,lat];
  if(!pointInRing(pt, r0)) return false;
  for(var k=1;k<rings.length;k++){
    var rk=unwrapRing(rings[k], refLon);
    if(pointInRing(pt, rk)) return false;
  }
  return true;
}
function bbox(r){
  var minLon=1e9,maxLon=-1e9,minLat=90,maxLat=-90;
  for(var i=0;i<r.length;i++){
    var L=r[i][0], A=r[i][1];
    if(L<minLon)minLon=L; if(L>maxLon)maxLon=L;
    if(A<minLat)minLat=A; if(A>maxLat)maxLat=A;
  }
  return {minLon,maxLon,minLat,maxLat};
}

onmessage=function(e){
  var geos=e.data.geos, step=Math.max(0.2, Math.min(6.0, e.data.tileDeg||1.0));
  var out=[];
  for(var p=0;p<geos.length;p++){
    var r0 = unwrapRing(geos[p].coordinates[0], 0);
    var bb = bbox(r0);
    var refLon = (bb.minLon+bb.maxLon)/2;
    r0 = unwrapRing(geos[p].coordinates[0], refLon);
    bb = bbox(r0);

    var latStart = Math.floor((bb.minLat-1)/step)*step;
    var latEnd   = Math.ceil((bb.maxLat+1)/step)*step;

    for(var lat=latStart; lat<=latEnd; lat+=step){
      var odd = Math.round(Math.abs(lat/step))%2;
      var lonStart = Math.floor((bb.minLon-1)/step)*step + (odd? step*0.5 : 0);
      var lonEnd   = Math.ceil((bb.maxLon+1)/step)*step;
      for(var lon=lonStart; lon<=lonEnd; lon+=step){
        var llLon = lon, llLat = Math.max(-90, Math.min(90, lat));
        if(containsUnwrapped(geos[p], refLon, llLon, llLat)){
          var v = vec3(wrap180(llLon), llLat);
          out.push(v[0],v[1],v[2]);
        }
      }
    }
  }
  var arr=new Float32Array(out);
  postMessage({ok:true, fill:arr}, [arr.buffer]);
};

